style.css:
@-moz-document domain("youtube.com") {
body {
    background: linear-gradient(to right, #ffeaff, #d0f0ff), 
                url("https://images.unsplash.com/photo-1503264116251-35a269479413?auto=format&fit=crop&w=1950&q=80");
    background-size: cover;
    background-attachment: fixed;
    background-position: center;
    font-family: "Segoe UI", sans-serif;
  }

  .anime-image-container {
    position: relative;
    border: 5px solid #ffb7ef;
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 0 25px rgba(255, 175, 238, 0.6), 0 0 60px rgba(200, 255, 255, 0.5);
    animation: float 6s ease-in-out infinite;
    max-width: 80%;
  }

  .anime-image-container img {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 20px;
  }

  .anime-caption {
    position: absolute;
    bottom: 10px;
    left: 10px;
    background: rgba(255, 255, 255, 0.7);
    padding: 6px 12px;
    border-radius: 12px;
    color: #5a5a5a;
    font-size: 14px;
    font-style: italic;
  }

  body::after {
    content: "";
    position: fixed;
    bottom: 20px;
    right: 20px;
    width: 200px;
    height: auto;
    z-index: 9999;
    background-image: url("https://i.pximg.net/img-original/img/2025/03/22/18/15/00/128485252_p0.jpg");
    background-size: cover;
    background-position: center;
    border-radius: 20px;
    box-shadow: 0 0 25px rgba(255, 175, 238, 0.5);
    border: 3px solid #ffd6f7;
    animation: float 6s ease-in-out infinite;
  }

  @keyframes float {
    0%, 100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-10px);
    }
  }
}
